func (x *MessageKeyRegistry) MessageKeys() *som.SomList[*MessageKeyEntry] {
	return som.NewSomList(x.Doc(), x.Path()+"/MSGKE-MKEY-LST", func(d *som.SpecDocument, p string) *MessageKeyEntry {
		return NewMessageKeyEntry(d, p)
	}, "MSGKE-MKEY-xxx")
}

